// Hunt: SharePoint web shells and w3wp.exe child processes (2026 SharePoint KEV cluster)
// CVE-2026-45659, CVE-2026-56164, CVE-2026-58644, CVE-2026-50522, CVE-2026-65660
let lookback = 30d;
// --- Section 1: Every ASPX/ASHX/ASMX file created under SharePoint TEMPLATE folders ---
// Compare against your known solution packages; web shells are usually small,
// recently created, and written by w3wp.exe, cmd.exe or powershell.exe.
let TemplateFiles = DeviceFileEvents
    | where TimeGenerated >= ago(lookback)
    | where ActionType in ("FileCreated", "FileModified", "FileRenamed")
    | where FolderPath has @"\Web Server Extensions\" and FolderPath has @"\TEMPLATE\"
    | where FileName endswith ".aspx" or FileName endswith ".ashx" or FileName endswith ".asmx"
    | summarize Writes = count(), FirstSeen = min(TimeGenerated), LastSeen = max(TimeGenerated),
                Writers = make_set(InitiatingProcessFileName, 5), Hashes = make_set(SHA256, 5)
        by DeviceName, FileName, FolderPath
    | extend HuntSection = "1-TemplateFiles";
// --- Section 2: Rare child processes of SharePoint w3wp.exe ---
// Stack-rank children across all SharePoint servers; anything seen on one host
// only a handful of times is worth investigating.
let W3wpChildren = DeviceProcessEvents
    | where TimeGenerated >= ago(lookback)
    | where InitiatingProcessFileName =~ "w3wp.exe"
    | where InitiatingProcessCommandLine has_any ("SharePoint", "SecurityTokenServiceApplicationPool")
    | where FileName !in~ ("csc.exe", "cvtres.exe", "vbc.exe", "conhost.exe", "werfault.exe")
    | summarize Executions = count(), FirstSeen = min(TimeGenerated), LastSeen = max(TimeGenerated),
                Devices = make_set(DeviceName, 10), SampleCommands = make_set(ProcessCommandLine, 5)
        by FileName
    | where Executions < 50
    | extend HuntSection = "2-RareW3wpChildren";
union TemplateFiles, W3wpChildren
| sort by HuntSection asc, FirstSeen asc
